template:
% 参数由系统自动注入：\def\k{1} \def\b{1} \def\showroot{1} \def\showyint{1} \def\showtriangle{0} \def\showpoint{0} \def\px{1.5} \def\labelp{P}
% 特征点：x 轴交点 A(-b/k,0)、y 轴交点 B(0,b)、点 P(px,k*px+b)
\pgfmathsetmacro{\kabs}{abs(\k)}
\ifdim\kabs pt>0.02pt
  \pgfmathsetmacro{\xint}{-\b/\k}
\else
  \pgfmathsetmacro{\xint}{999}
\fi
\pgfmathsetmacro{\py}{\k*\px+\b}
% x 视图范围：纳入原点、交点 A、点 P，原点两侧保证最小展宽
\pgfmathsetmacro{\xlo}{min(0,\px)-0.8}
\pgfmathsetmacro{\xhi}{max(0,\px)+0.8}
\ifdim\kabs pt>0.02pt
  \pgfmathsetmacro{\xlo}{min(\xlo,\xint-0.8)}
  \pgfmathsetmacro{\xhi}{max(\xhi,\xint+0.8)}
\fi
\pgfmathsetmacro{\xlo}{min(\xlo,-2.2)}
\pgfmathsetmacro{\xhi}{max(\xhi,2.2)}
\pgfmathtruncatemacro{\xleft}{floor(\xlo)}
\pgfmathtruncatemacro{\xright}{ceil(\xhi)}
% y 视图以特征点为准；直线在边缘处过高/过低时封顶 8 个单位
\pgfmathsetmacro{\ytopfeat}{max(0,\b,\py)}
\pgfmathsetmacro{\ybotfeat}{min(0,\b,\py)}
\pgfmathsetmacro{\yedgeL}{\k*\xleft+\b}
\pgfmathsetmacro{\yedgeR}{\k*\xright+\b}
\pgfmathsetmacro{\ytop}{max(\ytopfeat,min(max(\yedgeL,\yedgeR),\ytopfeat+8.0))+0.8}
\pgfmathsetmacro{\ybottom}{min(\ybotfeat,max(min(\yedgeL,\yedgeR),\ybotfeat-8.0))-0.8}
\pgfmathtruncatemacro{\ytop}{ceil(\ytop)}
\pgfmathtruncatemacro{\ybottom}{floor(\ybottom)}
% 直线绘制域：截断到视图上下边之外一点
\ifdim\kabs pt>0.02pt
  \pgfmathsetmacro{\xtop}{(\ytop+0.3-\b)/\k}
  \pgfmathsetmacro{\xbot}{(\ybottom-0.3-\b)/\k}
  \pgfmathsetmacro{\dlo}{max(\xleft,min(\xtop,\xbot))}
  \pgfmathsetmacro{\dhi}{min(\xright,max(\xtop,\xbot))}
\else
  \pgfmathsetmacro{\dlo}{\xleft}
  \pgfmathsetmacro{\dhi}{\xright}
\fi
\pgfmathsetmacro{\xrange}{\xright-\xleft}
\pgfmathsetmacro{\yrange}{\ytop-\ybottom}
\pgfmathsetmacro{\figscale}{6.5/max(\xrange,\yrange)}
\pgfmathsetmacro{\dotr}{1.6/\figscale}
\begin{tikzpicture}[scale=\figscale, every node/.style={font=\small, fill=none, inner sep=1.5pt}]
  % ===== 坐标系 =====
  \draw[->, thick] (\xleft-0.5,0) -- (\xright+0.6,0) node[right] {$x$};
  \draw[->, thick] (0,\ybottom-0.5) -- (0,\ytop+0.6) node[above] {$y$};
  \node[below left, font=\tiny] at (0,0) {$O$};
  \foreach \x in {\xleft,...,\xright} {
    \ifnum\x=0\else
      \draw (\x,0.12/\figscale) -- (\x,-0.12/\figscale);
      \node[below, font=\tiny, inner sep=1pt] at (\x,0) {$\x$};
    \fi
  }
  \foreach \y in {\ybottom,...,\ytop} {
    \ifnum\y=0\else
      \draw (0.12/\figscale,\y) -- (-0.12/\figscale,\y);
      \node[left, font=\tiny, inner sep=1pt] at (0,\y) {$\y$};
    \fi
  }
  % ===== 三角形 AOB =====
  \ifnum\showtriangle>0
    \ifdim\kabs pt>0.02pt
      \pgfmathsetmacro{\xintabs}{abs(\xint)}
      \pgfmathsetmacro{\babs}{abs(\b)}
      \ifdim\xintabs pt>0.05pt
        \ifdim\babs pt>0.05pt
          \fill[blue!10, draw=none] (\xint,0) -- (0,0) -- (0,\b) -- cycle;
          \pgfmathsetmacro{\rmk}{0.28/\figscale}
          \draw[gray] (\rmk,0) -- (\rmk,\rmk) -- (0,\rmk);
        \fi
      \fi
    \fi
  \fi
  % ===== 直线 =====
  \draw[thick] (\dlo,{\k*\dlo+\b}) -- (\dhi,{\k*\dhi+\b});
  % ===== 与 x 轴交点 A =====
  \ifnum\showroot>0
    \ifdim\kabs pt>0.02pt
      \pgfmathsetmacro{\xintabs}{abs(\xint)}
      \ifdim\xintabs pt>0.05pt
        \fill (\xint,0) circle [radius=\dotr pt];
        \node[below=1pt, font=\tiny, inner sep=1pt] at (\xint,0) {$A$};
      \fi
    \fi
  \fi
  % ===== 与 y 轴交点 B =====
  \ifnum\showyint>0
    \pgfmathsetmacro{\babs}{abs(\b)}
    \ifdim\babs pt>0.05pt
      \fill (0,\b) circle [radius=\dotr pt];
      \node[left, font=\tiny] at (0,\b) {$B$};
    \fi
  \fi
  % ===== 直线上点 P =====
  \ifnum\showpoint>0
    \fill (\px,\py) circle [radius=\dotr pt];
    \node[above right, font=\tiny] at (\px,\py) {$\labelp$};
  \fi
\end{tikzpicture}
